contract InvMutTest {
    C c;
    constructor() payable { c = new C{value: 1 ether}(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint amount) public payable {
        // Fresh C: no guess has ever been locked, so settle() must revert
        // and must not move any Ether out of c.
        uint balBefore = address(c).balance;

        bool settleReverted;
        c.settle(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { settleReverted = true; } else { settleReverted = false; }

        assert(settleReverted && address(c).balance == balBefore && amount == amount);
    }

    receive() external payable {}
}

