pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PredictTheBlockHashChallenge c;

    function setUp() public {
        vm.deal(address(this), 1 ether);
        c = new PredictTheBlockHashChallenge{value: 1 ether}();
    }

    function _run(uint256 amount) internal {
        uint balBefore = address(c).balance;
        bool settleReverted;
        try c.settle() { settleReverted = false; } catch { settleReverted = true; }
        assertTrue(settleReverted && address(c).balance == balBefore && amount == amount);
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
